import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem125 preserva oferta e afiliado',()=>{for(const [id,titulo,expected,link] of [["PP8JorVbOJNMg5FXOr47","Esteira Elétrica Ergométrica Dobrável 12km C/tela Led Bivolt","Esteira elétrica dobrável com visor LED anunciado","https://www.mercadolivre.com.br/up/MLBU3640141455?pdp_filters=item_id%3AMLB4337879731"],["ppQhZEUfZDuGcIZRmFB5","Serra Tico Tico Profissional 500w 3000 Gpm Lâmina E Protetor Bst500 The Black Tools","Serra tico-tico The Black Tools BST500 — 500 W anunciados","https://www.mercadolivre.com.br/p/MLB26715512?pdp_filters=item_id%3AMLB4037910198"],["q8wxWRl86XmL7Gglikg7","Kaiak Ultra Natura Colônia Perfume Masculino 100ml Relançamento 2025","Natura Kaiak Ultra masculino — 100 mL anunciados","https://www.mercadolivre.com.br/p/MLB45358161?wid=MLB4085175433"]]){const p={id,titulo,link,linkAfiliado:'https://meli.la/preservar',preco:'preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);assert.equal(x.titulo,expected);for(const k of ['id','link','linkAfiliado','preco'])assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);}});
